INSERT INTO periods (period_id, period_name, start_year, end_year) VALUES
 ('PER_YARSAN','Yarsan / Ahl-e Haqq Period',1300,2025)
INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_HAMZEHEE_YARESAN','secondary scholarship','M. Reza Hamzeh''ee, The Yaresan: A Sociological, Historical and Religio-Historical Study of a Kurdish Community (1990)','Foundational ethnographic and historical study of Yarsan theology, the Haftan, and the manifestation doctrine.'),
 ('SRC_MIRHOSSEINI_AHLEHAQQ','secondary scholarship','Ziba Mir-Hosseini, Inner Truth and Outer History: The Two Worlds of the Ahl-i Haqq of Kurdistan (IJMES 1994)','Ethnography of Ahl-e Haqq belief, the ritual jam, and the doctrine of successive divine manifestations.'),
 ('SRC_VANBRUINESSEN_AHLEHAQQ','secondary scholarship','Martin van Bruinessen, studies on Ahl-i Haqq and Kurdish heterodox religions','Comparative study placing Yarsan among Kurdish heterodox traditions and relating it to Alevi-Bektashi currents.')
INSERT INTO _e VALUES
 ('ENT_YRS_HAFTAN','The Haftan (The Seven)','Holy collective','Angelic collective','Yarsan','divine manifestation; angelology','B','The seven primordial holy beings/angels who manifest with each divine theophany; the central angelic heptad of Yarsan cosmology, attested in the Kalam and Hamzeh''ee.'),
 ('ENT_YRS_HAFTAWANE','The Haftawane (The Seven Other)','Holy collective','Angelic collective','Yarsan','angelology','C','A second order of seven holy beings ranked beneath the Haftan in Yarsan angelic hierarchy (Hamzeh''ee).'),
 ('ENT_YRS_SULTAN_SAHAK','Sultan Sahak','Divine manifestation','Divine manifestation','Yarsan','divine manifestation; founder','B','Soltan Sohak, the central manifestation of the Divine Essence who instituted the present Yarsan dispensation (c. 14th-15th c. Kurdistan); founder figure (Hamzeh''ee, Mir-Hosseini).'),
 ('ENT_YRS_KHAWANDAGAR','Khawandagar','Divine manifestation','Divine manifestation','Yarsan','creator; divine manifestation','C','The first/primordial manifestation of the Divine Essence (Lord-Creator) in the Yarsan chain of mazhariyya (Hamzeh''ee).'),
 ('ENT_YRS_SHAH_KHOSHIN','Shah Khoshin','Divine manifestation','Divine manifestation','Yarsan','divine manifestation','C','A manifestation of the Divine Essence in the Yarsan succession, placed between Ali and Sultan Sahak in the chain of theophanies (Hamzeh''ee).'),
 ('ENT_YRS_PIR_BENJAMIN','Pir Benjamin (Binyamin)','Holy figure','Angelic being','Yarsan','angelology; spiritual guide','C','Foremost of the Haftan, the pir (spiritual master) figure of the heptad in the Sultan Sahak cycle (Hamzeh''ee). Distinct Yarsan figure, not the Israelite patriarch Benjamin (ENT_ISR_BENJAMIN).'),
 ('ENT_YRS_DAWUD','Dawud (Yarsan Haftan)','Holy figure','Angelic being','Yarsan','angelology','C','One of the Haftan, the dalil (guide) figure of the heptad in the Sultan Sahak cycle (Hamzeh''ee). HOMONYM: distinct from the Islamic prophet Dawud/David (ENT_ISL_DAWUD); renamed for disambiguation.'),
 ('ENT_YRS_PIR_MUSI','Pir Musi','Holy figure','Angelic being','Yarsan','angelology; recording','C','One of the Haftan, associated with the recording/scribe function (keeper of deeds) in Yarsan angelology (Hamzeh''ee).'),
 ('ENT_YRS_MOSTAFA_DAWAN','Mostafa Dawan','Holy figure','Angelic being','Yarsan','angelology','C','One of the Haftan in the Sultan Sahak cycle (Hamzeh''ee).'),
 ('ENT_YRS_RAMZBAR','Ramzbar','Holy figure','Divine feminine/aeon','Yarsan','divine feminine; angelology','C','Female holy figure (Razbar/Ramzbar) associated with the Haftan and the Sultan Sahak cycle; one of the few feminine holy figures in Yarsan tradition (Hamzeh''ee, Mir-Hosseini).'),
 ('ENT_YRS_DIVINE_ESSENCE','Divine Essence (Dhat / Haqq)','Supreme principle','Godhead/principle','Yarsan','godhead; supreme principle','C','The hidden Divine Essence (Haqq) whose successive human manifestations structure Yarsan theology (Mir-Hosseini).'),
 ('ENT_YRS_MAZHARIYYA','Mazhariyya (chain of manifestation)','Doctrine','Mystical doctrine/category','Yarsan','theology; manifestation doctrine','C','The doctrine of successive theophanies/manifestations of the Divine Essence in human form (Khawandagar -> Ali -> Shah Khoshin -> Sultan Sahak) (Hamzeh''ee, Mir-Hosseini).'),
 ('ENT_YRS_JAM','Jam (ritual assembly)','Ritual category','Ritual category','Yarsan','ritual; communal worship','C','The communal ritual assembly (jam/jamkhana) central to Yarsan worship, with the votive offering and music; only its public form is modeled here (Mir-Hosseini).'),
 ('ENT_YRS_KALAM','Kalam-e Saranjam','Sacred text','Sacred text/principle','Yarsan','scripture; sacred text','C','The corpus of sacred Gorani-language hymns/discourses (Kalam, esp. Saranjam) transmitting Yarsan cosmology and the manifestations (Hamzeh''ee).');
