INSERT INTO _p VALUES
 ('ENT_YRS_HAFTAN','PER_YARSAN','The seven primordial holy beings/angels who manifest with each divine theophany; the central angelic heptad of Yarsan cosmology, attested in the Kalam and Hamzeh''ee.'),
 ('ENT_YRS_HAFTAWANE','PER_YARSAN','A second order of seven holy beings ranked beneath the Haftan in Yarsan angelic hierarchy (Hamzeh''ee).'),
 ('ENT_YRS_SULTAN_SAHAK','PER_YARSAN','Soltan Sohak, the central manifestation of the Divine Essence who instituted the present Yarsan dispensation (c. 14th-15th c. Kurdistan); founder figure (Hamzeh''ee, Mir-Hosseini).'),
 ('ENT_YRS_KHAWANDAGAR','PER_YARSAN','The first/primordial manifestation of the Divine Essence (Lord-Creator) in the Yarsan chain of mazhariyya (Hamzeh''ee).'),
 ('ENT_YRS_SHAH_KHOSHIN','PER_YARSAN','A manifestation of the Divine Essence in the Yarsan succession, placed between Ali and Sultan Sahak in the chain of theophanies (Hamzeh''ee).'),
 ('ENT_YRS_PIR_BENJAMIN','PER_YARSAN','Foremost of the Haftan, the pir (spiritual master) figure of the heptad in the Sultan Sahak cycle (Hamzeh''ee). Distinct Yarsan figure, not the Israelite patriarch Benjamin (ENT_ISR_BENJAMIN).'),
 ('ENT_YRS_DAWUD','PER_YARSAN','One of the Haftan, the dalil (guide) figure of the heptad in the Sultan Sahak cycle (Hamzeh''ee). HOMONYM: distinct from the Islamic prophet Dawud/David (ENT_ISL_DAWUD); renamed for disambiguation.'),
 ('ENT_YRS_PIR_MUSI','PER_YARSAN','One of the Haftan, associated with the recording/scribe function (keeper of deeds) in Yarsan angelology (Hamzeh''ee).'),
 ('ENT_YRS_MOSTAFA_DAWAN','PER_YARSAN','One of the Haftan in the Sultan Sahak cycle (Hamzeh''ee).'),
 ('ENT_YRS_RAMZBAR','PER_YARSAN','Female holy figure (Razbar/Ramzbar) associated with the Haftan and the Sultan Sahak cycle; one of the few feminine holy figures in Yarsan tradition (Hamzeh''ee, Mir-Hosseini).'),
 ('ENT_YRS_DIVINE_ESSENCE','PER_YARSAN','The hidden Divine Essence (Haqq) whose successive human manifestations structure Yarsan theology (Mir-Hosseini).'),
 ('ENT_YRS_MAZHARIYYA','PER_YARSAN','The doctrine of successive theophanies/manifestations of the Divine Essence in human form (Khawandagar -> Ali -> Shah Khoshin -> Sultan Sahak) (Hamzeh''ee, Mir-Hosseini).'),
 ('ENT_YRS_JAM','PER_YARSAN','The communal ritual assembly (jam/jamkhana) central to Yarsan worship, with the votive offering and music; only its public form is modeled here (Mir-Hosseini).'),
 ('ENT_YRS_KALAM','PER_YARSAN','The corpus of sacred Gorani-language hymns/discourses (Kalam, esp. Saranjam) transmitting Yarsan cosmology and the manifestations (Hamzeh''ee).');
