INSERT INTO _r VALUES
 ('ENT_YRS_PIR_BENJAMIN','member_of','ENT_YRS_HAFTAN','high','Pir Benjamin (Binyamin) is the foremost of the Haftan in Yarsan tradition (Hamzeh''ee).'),
 ('ENT_YRS_DAWUD','member_of','ENT_YRS_HAFTAN','high','Dawud is counted among the Seven (Haftan) in the Sultan Sahak cycle (Hamzeh''ee).'),
 ('ENT_YRS_PIR_MUSI','member_of','ENT_YRS_HAFTAN','high','Pir Musi is one of the Haftan, with a recording/scribe function (Hamzeh''ee).'),
 ('ENT_YRS_MOSTAFA_DAWAN','member_of','ENT_YRS_HAFTAN','high','Mostafa Dawan is counted among the Haftan (Hamzeh''ee).'),
 ('ENT_YRS_RAMZBAR','member_of','ENT_YRS_HAFTAN','medium','Ramzbar, the female holy figure, is associated with the Haftan cycle of Sultan Sahak (Hamzeh''ee, Mir-Hosseini).'),
 ('ENT_YRS_HAFTAWANE','member_of','ENT_YRS_HAFTAN','medium','The Haftawane (Seven Other) form the secondary order ranked beneath the Haftan in Yarsan angelology (Hamzeh''ee).'),
 ('ENT_YRS_SULTAN_SAHAK','presides_over','ENT_YRS_HAFTAN','high','Sultan Sahak, the central manifestation, gathers and presides over the Haftan of his cosmic cycle (Hamzeh''ee).'),
 ('ENT_YRS_SULTAN_SAHAK','reception_of','ENT_YRS_SHAH_KHOSHIN','high','Sultan Sahak is the manifestation of the Divine Essence succeeding Shah Khoshin in the Yarsan chain of mazhariyya (Hamzeh''ee).'),
 ('ENT_YRS_SHAH_KHOSHIN','reception_of','ENT_ISL_ALI','high','In the Yarsan chain of manifestations the theophany passes Khawandagar -> Ali -> Shah Khoshin; Shah Khoshin re-manifests the Essence borne by Ali (Hamzeh''ee, Mir-Hosseini). Object ENT_ISL_ALI verified existing.'),
 ('ENT_ISL_ALI','reception_of','ENT_YRS_KHAWANDAGAR','medium','Yarsan doctrine reinterprets the historical Imam Ali (existing ENT_ISL_ALI) as a manifestation of the Divine Essence succeeding the primordial Khawandagar in the chain of mazhariyya (Hamzeh''ee). Same entity, reinterpreted by Yarsan theology.'),
 ('ENT_YRS_SULTAN_SAHAK','embodies','ENT_YRS_DIVINE_ESSENCE','high','Sultan Sahak is held to be a human manifestation (mazhar) embodying the hidden Divine Essence (Dhat) (Mir-Hosseini).'),
 ('ENT_YRS_KHAWANDAGAR','embodies','ENT_YRS_DIVINE_ESSENCE','medium','Khawandagar is the first manifestation embodying the Divine Essence in Yarsan cosmology (Hamzeh''ee).'),
 ('ENT_YRS_SHAH_KHOSHIN','embodies','ENT_YRS_DIVINE_ESSENCE','medium','Shah Khoshin embodies the Divine Essence as one theophany in the manifestation chain (Hamzeh''ee).'),
 ('ENT_YRS_MAZHARIYYA','emanates_from','ENT_YRS_DIVINE_ESSENCE','medium','The doctrine of mazhariyya describes how successive manifestations issue from the hidden Divine Essence (Mir-Hosseini).'),
 ('ENT_YRS_JAM','ritual_associated_with','ENT_YRS_SULTAN_SAHAK','high','The jam assembly is instituted in the cycle of Sultan Sahak and centers Yarsan communal worship (Mir-Hosseini). Direction corrected to ritual->figure per DB convention.'),
 ('ENT_YRS_HAFTAN','participates_in_creation','ENT_YRS_JAM','medium','The archetypal first jam is held among the Haftan at creation in the Kalam, the model for the earthly assembly (Hamzeh''ee).'),
 ('ENT_YRS_KALAM','transmits','ENT_YRS_MAZHARIYYA','medium','The Kalam-e Saranjam records and transmits the doctrine of successive manifestations (Hamzeh''ee).'),
 ('ENT_YRS_KALAM','reveals','ENT_YRS_SULTAN_SAHAK','low','The acts and teaching of Sultan Sahak are preserved and revealed through the Kalam-e Saranjam corpus (Hamzeh''ee). Direction corrected to revealer->revealed (the prior revealed_by edge was backwards and that verb is unused in the DB).'),
 ('ENT_YRS_HAFTAN','aligned_with','ENT_SUF_BEKTASHI','medium','Yarsan heptadic angelology and ghulat manifestation theology are functionally aligned with the Alevi-Bektashi heterodox current (van Bruinessen). Object ENT_SUF_BEKTASHI verified existing.'),
 ('ENT_YRS_SULTAN_SAHAK','aligned_with','ENT_SUF_BEKTASH','low','Sultan Sahak as a venerated founder-manifestation parallels Hajji Bektash Wali in the comparative typology of Kurdish/Anatolian heterodoxy (van Bruinessen). Object ENT_SUF_BEKTASH verified existing.'),
 ('ENT_YRS_DIVINE_ESSENCE','aligned_with','ENT_SUF_HALLAJ','low','Yarsan tradition reveres al-Hallaj as a figure of the manifest Haqq; his ''ana al-Haqq'' resonates with Yarsan manifestation doctrine (Hamzeh''ee). Object ENT_SUF_HALLAJ verified existing.');
